#include <stdio.h>

void add_one(int *n) {
    (*n)++;
}

void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int main(void) {
    int x = 5;
    int y = 9;
    add_one(&x);
    printf("%d\n", x);
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}

